import{r as generateSecureInt}from"./secure-random-C3MxPnYY.mjs";
//!src/agents/session-slug.ts
const SLUG_ADJECTIVES=[`amber`,`briny`,`brisk`,`calm`,`clear`,`cool`,`crisp`,`dawn`,`delta`,`ember`,`faint`,`fast`,`fresh`,`gentle`,`glow`,`good`,`grand`,`keen`,`kind`,`lucky`,`marine`,`mellow`,`mild`,`neat`,`nimble`,`nova`,`oceanic`,`plaid`,`quick`,`quiet`,`rapid`,`salty`,`sharp`,`swift`,`tender`,`tidal`,`tidy`,`tide`,`vivid`,`warm`,`wild`,`young`];const SLUG_NOUNS=[`atlas`,`basil`,`bison`,`bloom`,`breeze`,`canyon`,`cedar`,`claw`,`cloud`,`comet`,`coral`,`cove`,`crest`,`crustacean`,`daisy`,`dune`,`ember`,`falcon`,`fjord`,`forest`,`glade`,`gulf`,`harbor`,`haven`,`kelp`,`lagoon`,`lobster`,`meadow`,`mist`,`nudibranch`,`nexus`,`ocean`,`orbit`,`otter`,`pine`,`prairie`,`reef`,`ridge`,`river`,`rook`,`sable`,`sage`,`seaslug`,`shell`,`shoal`,`shore`,`slug`,`summit`,`tidepool`,`trail`,`valley`,`wharf`,`willow`,`zephyr`];const CRUSTACEAN_NOUNS=[`barnacle`,`claw`,`crab`,`crayfish`,`krill`,`langoustine`,`lobster`,`prawn`,`shrimp`,`shell`];function randomChoice(e,t){return e[generateSecureInt(e.length)]??t}const SLUG_FALLBACK_ALPHABET=`abcdefghijklmnopqrstuvwxyz0123456789`;function createFallbackSuffix(e){let t=``;for(let n=0;n<e;n+=1)t+=SLUG_FALLBACK_ALPHABET[generateSecureInt(36)]??`x`;return t}function createSlugBase(e=2,t=SLUG_NOUNS){const n=[randomChoice(SLUG_ADJECTIVES,`steady`),randomChoice(t,`harbor`)];if(e>2)n.push(randomChoice(t,`reef`));return n.join(`-`)}function createAvailableSlug(e,t,n=SLUG_NOUNS){for(let r=0;r<12;r+=1){const r=createSlugBase(e,n);if(!t(r))return r;for(let e=2;e<=12;e+=1){const n=`${r}-${e}`;if(!t(n))return n}}}function createUniqueSlug(e,t){const n=t??(()=>false);for(const t of[2,3]){const r=createAvailableSlug(t,n,e);if(r)return r}const r=`${createSlugBase(3,e)}-${createFallbackSuffix(3)}`;return n(r)?`${r}-${Date.now().toString(36)}`:r}function createSessionSlug(e){return createUniqueSlug(SLUG_NOUNS,e)}function createCrustaceanSlug(e){return createUniqueSlug(CRUSTACEAN_NOUNS,e)}export{createSessionSlug as n,createCrustaceanSlug as t};